-- 1. CIDADES (CITIES)
INSERT INTO public.cities (id, name, slug, state, country, description, is_active)
VALUES
    ('00000000-0000-0000-0000-000000000001', 'São Roque', 'sao-roque', 'SP', 'Brasil', 'A Estância Turística de São Roque é a capital paulista do enoturismo, famosa pelo histórico Roteiro do Vinho, culinária portuguesa e italiana, clima acolhedor de serra e belezas naturais.', true),
    ('00000000-0000-0000-0000-000000000002', 'Atibaia', 'atibaia', 'SP', 'Brasil', 'Conhecida como a Capital Nacional do Morango e das Flores, Atibaia encanta com o Monumento Natural da Pedra Grande (1.418m), clima privilegiado, polo cervejeiro artesanal e hotelaria de alto padrão.', true),
    ('00000000-0000-0000-0000-000000000003', 'Socorro', 'socorro', 'SP', 'Brasil', 'Capital nacional do turismo de aventura e referência internacional em ecoturismo acessível. Famosa pelo rafting no Rio do Peixe, pôr do sol na Pedra Bela Vista, gastronomia caipira e compras de malhas.', true)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    description = EXCLUDED.description,
    is_active = true;

