    ('10000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000001', 'Restaurantes & Gastronomia', 'restaurantes', 'Gastronomia portuguesa, cantinas italianas, pratos com alcachofra e carnes nobres na brasa.', 'Utensils', true),
