    ('30000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000003', 'Natureza & Mirantes', 'natureza-mirantes-socorro', 'Mirante Pedra Bela Vista, Gruta do Anjo, Mirante do Cristo e cachoeiras cristalinas.', 'Mountain', true),
