-- 3. ESTABELECIMENTOS REAIS (BUSINESSES)
-- SÃO ROQUE
INSERT INTO public.businesses (id, city_id, category_id, name, slug, description, address, phone, whatsapp, instagram, website, price_min, price_max, opening_hours, main_image_url, status, plan, is_featured, is_premium)
VALUES
    ('11000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'Vinícola Góes', 'vinicola-goes', 'A mais tradicional e premiada vinícola de São Roque. Oferece passeios guiados pelos vinhedos e caves subterrâneas, degustações orientadas por enólogos, restaurante com vista panorâmica e loja completa de vinhos finos e sucos de uva integrais.', 'Estrada do Vinho, km 9 - Canguera, São Roque - SP', '(11) 4711-3500', '5511997873500', 'vinicolagoes', 'https://vinicolagoes.com.br', 45, 220, 'Segunda a Domingo, das 09h às 18h', 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('11000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'Quinta do Olivardo', 'quinta-do-olivardo', 'Uma imersão encantadora na cultura açoriana e portuguesa em pleno Roteiro do Vinho. Famosa pelos pastéis de nata fresquinhos servidos ao toque do sino, o tradicional Vinho dos Mortos, bacalhau na brasa, tirolesa infantil e parreirais em socalcos.', 'Estrada do Vinho, km 4 - Sorocamirim, São Roque - SP', '(11) 4711-1100', '5511970881000', 'quintadoolivardo', 'https://quintadoolivardo.com.br', 60, 250, 'Segunda a Domingo, das 09h30 às 17h30', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('11000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'Cantina Tia Lina', 'cantina-tia-lina', 'Referência em culinária italiana artesanal no Roteiro do Vinho. Famosa pelo clássico Rondelli quatro queijos com alcachofra cultivada na cidade, polenta cremosa com ragu de linguiça e carta de vinhos regionais.', 'Estrada do Vinho, km 10,4 - Canguera, São Roque - SP', '(11) 4711-2018', '5511999882018', 'cantinatialina', 'https://cantinatialina.com.br', 75, 180, 'Sexta a Domingo e Feriados, das 11h30 às 17h', 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', true, false),
    ('11000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'Vila Don Patto', 'vila-don-patto', 'Amplo complexo enogastronômico e turístico integrado à Mata Atlântica. Dispõe de restaurante português de alta gastronomia, restaurante italiano, boulangerie artesanal, empório gourmet, cafeteria e amplo espaço kids.', 'Estrada do Vinho, km 2,5 - Sorocamirim, São Roque - SP', '(11) 4711-3001', '5511975632001', 'viladonpatto', 'https://viladonpatto.com.br', 80, 280, 'Segunda a Domingo, das 09h às 17h30', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('11000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'Vinícola Canguera', 'vinicola-canguera', 'Fundada no início dos anos 1950, a Canguera abriga o Museu do Vinho de São Roque, tonéis gigantes de carvalho centenários e degustação orientada de licores artesanais, frisantes e vinhos finos.', 'Estrada do Vinho, km 8 - Canguera, São Roque - SP', '(11) 4711-1404', '5511998551404', 'vinicolacanguera', 'https://vinicolacanguera.com.br', 30, 150, 'Segunda a Domingo, das 09h às 17h30', 'https://images.unsplash.com/photo-1528823872057-9c018a7a7553?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', true, false),
    ('11000000-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000003', 'Hotel Villa Rossa', 'hotel-villa-rossa', 'Resort de luxo encravado em 350 mil m² de Mata Atlântica preservada. Possui spa privativo, piscinas climatizadas e aquecidas, gastronomia internacional e suítes com lareira.', 'Rua Cora Coralina, 350 - Vila Darcy Penteado, São Roque - SP', '(11) 4713-5560', '5511964555560', 'hotelvillarossa', 'https://villarossa.com.br', 850, 2200, 'Recepção 24 horas', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('11000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000003', 'Pousada Acalanto da Serra', 'pousada-acalanto-da-serra', 'Refúgio romântico e aconchegante para casais. Oferece chalés rústicos equipados com banheira de hidromassagem dupla, lareira a lenha e café colonial artesanal.', 'Estrada da Serrinha, 800 - Ibaté, São Roque - SP', '(11) 4712-4422', '5511973344422', 'pousadaacalantodaserra', NULL, 420, 980, 'Check-in: 14h / Check-out: 12h', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', true, false),
    ('11000000-0000-0000-0000-000000000008', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000004', 'Ski Mountain Park', 'ski-mountain-park', 'Parque temático de montanha situado a 1.200m de altitude com pistas artificiais de esqui e snowboard, tobogã gigante, arvorismo, tirolesa e restaurante de montanha.', 'Estrada da Serrinha, s/n - Cambará, São Roque - SP', '(11) 4712-3299', '5511996553299', 'skipark_oficial', 'https://skipark.com.br', 50, 160, 'Sexta a Domingo e Feriados, das 09h às 17h', 'https://images.unsplash.com/photo-1551698618-1dfe5d97d256?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('11000000-0000-0000-0000-000000000009', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'Restaurante Cascudo', 'restaurante-cascudo', 'Especializado em carnes nobres grelhadas na brasa e gastronomia caipira refinada. Ambiente aconchegante rodeado de jardins floridos no Roteiro do Vinho.', 'Estrada do Vinho, km 6 - Sorocamirim, São Roque - SP', '(11) 4711-2550', '5511998332550', 'restaurantecascudo', NULL, 70, 190, 'Quinta a Domingo, das 11h30 às 17h', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1000&q=80', 'published', 'free', false, false),
    ('11000000-0000-0000-0000-000000000010', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000005', 'Empório & Alcachofras São Roque', 'emporio-alcachofras-sao-roque', 'Ponto de parada tradicional para alcachofras frescas cultivadas na região, fundos de alcachofra em conserva, queijos artesanais, vinhos e o famoso licor de alcachofra.', 'Estrada do Vinho, km 1 - Sorocamirim, São Roque - SP', '(11) 4711-1880', '5511971221880', 'alcachofrassaoroque', NULL, 25, 120, 'Todos os dias, das 09h às 18h', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1000&q=80', 'published', 'free', false, false),

-- ATIBAIA
    ('22000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000002', 'Clube Atibaiense de Voo Livre (CAVL)', 'clube-atibaiense-de-voo-livre-cavl', 'Associação oficial de voo livre de São Paulo. Voos duplos de instrução em parapente e asa-delta saltando da rampa da Pedra Grande (1.418m) com instrutores certificados CBVL e fotos em 4K.', 'Monumento Natural da Pedra Grande - Estrada da Pedra Grande, Atibaia - SP', '(11) 99876-5432', '5511998765432', 'cavl_atibaia', 'https://voolivreatibaia.com.br', 380, 650, 'Sábado e Domingo, das 08h às 18h', 'https://images.unsplash.com/photo-1507034589631-9433cc6bc453?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('22000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000006', 'Orquidário & Morangos Takebayashi', 'orquidario-morangos-takebayashi', 'Cultivo protegido de orquídeas raras, colheita de morangos hidropônicos frescos diretamente nos canteiros e cafeteria colonial com doces caseiros da fazenda.', 'Estrada dos Pires, 1200 - Bairro dos Pires, Atibaia - SP', '(11) 4416-1234', '5511987654321', 'orquidariotakebayashi', 'https://takebayashi.com.br', 30, 160, 'Terça a Domingo, das 09h às 17h', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('22000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000004', 'Bourbon Atibaia Resort', 'bourbon-atibaia-resort', 'Resort premiado com complexo aquático aquecido, spa com terapias relaxantes, espaço Turma da Mônica, centro gastronômico com diversos restaurantes e área verde de 400 mil m².', 'Rodovia Fernão Dias, km 37,5 - Jardim Samambaia, Atibaia - SP', '(11) 4414-4700', '5511976543210', 'bourbonatibaia', 'https://bourbon.com.br/resort/bourbon-atibaia', 1200, 3400, 'Recepção 24 horas', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('22000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000005', 'Parque Municipal Edmundo Zanoni & Teleférico', 'parque-edmundo-zanoni-teleferico', 'Cartão-postal no centro de Atibaia com lago com pedalinhos, Museu de História Natural, Salão do Artesão e estação de embarque do Teleférico para o Lago do Major.', 'Av. Horácio Netto, 1030 - Samambaia Parque Residencial, Atibaia - SP', '(11) 4414-0400', '5511965432109', 'turismoatibaia', NULL, 20, 50, 'Terça a Domingo, das 09h às 18h', 'https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', true, false),
    ('22000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000003', 'Cervejaria Freising Haus', 'cervejaria-freising-haus', 'Cervejaria em autêntico estilo bávaro germânico com chopes puros malte produzidos conforme a Lei de Pureza de 1516, pratos alemães clássicos e biergarten climatizado.', 'Av. Jerônimo de Camargo, 7860 - Jardim do Lago, Atibaia - SP', '(11) 4412-1516', '5511954321098', 'freisinghaus', 'https://freisinghaus.com.br', 55, 180, 'Quarta a Domingo, das 12h às 23h30', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('22000000-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000003', 'San Costilla Carnes Especiais', 'san-costilla-carnes-especiais', 'A casa de carnes de referência na Alameda Lucas. Cortes nobres Angus na parrilla aberta, bife de ancho, picanha premium e excelente carta de vinhos.', 'Alameda Lucas Nogueira Garcez, 2574 - Jardim Paulista, Atibaia - SP', '(11) 4411-8899', '5511943210987', 'sancostillaatibaia', NULL, 80, 260, 'Segunda a Domingo, das 11h30 às 23h', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', true, false),
    ('22000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000003', 'Romano Restaurante & Pizzaria', 'romano-restaurante-pizzaria', 'Pizzas artesanais de massa de fermentação lenta de 48h assadas em forno a lenha, massas frescas e sobremesas italianas.', 'Alameda Lucas Nogueira Garcez, 1980 - Jardim Paulista, Atibaia - SP', '(11) 4412-5500', '5511932109876', 'romanopizzariaatibaia', NULL, 60, 160, 'Terça a Domingo, das 18h30 às 23h30', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', false, false),
    ('22000000-0000-0000-0000-000000000008', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000003', 'Cervejaria Los Compadres Brewpub', 'cervejaria-los-compadres-brewpub', 'Brewpub premiado em Atibaia com 14 torneiras de chope artesanal produzidos no local, hambúrgueres na brasa e música ao vivo.', 'Av. Joviano Alvim, 1370 - Atibaia Jardim, Atibaia - SP', '(11) 4413-2211', '5511921098765', 'loscompadrescervejaria', NULL, 40, 130, 'Quinta a Domingo, das 17h às 00h', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=1000&q=80', 'published', 'free', false, false),
    ('22000000-0000-0000-0000-000000000009', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000004', 'Pousada Refúgio do Saci', 'pousada-refugio-do-saci', 'Pousada ecológica em meio à mata nativa com chalés aconchegantes com lareira e hidro, piscina natural e café colonial com produtos da fazenda.', 'Estrada dos Pires, 1800 - Portão, Atibaia - SP', '(11) 4416-8900', '5511910987654', 'pousadarefugiodosaci', NULL, 390, 850, 'Check-in: 14h / Check-out: 12h', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1000&q=80', 'published', 'free', false, false),
    ('22000000-0000-0000-0000-000000000010', '00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000001', 'Monumento Natural Estadual da Pedra Grande', 'monumento-natural-pedra-grande-atibaia', 'O cartão-postal de Atibaia a 1.418 metros de altitude com vista panorâmica de 360° para a Serra da Mantiqueira e rampa de voo livre.', 'Acesso pela Estrada da Pedra Grande, s/n - Atibaia - SP', '(11) 4412-2884', '5511988882884', 'pedragrandeatibaia', NULL, 0, 0, 'Aberto diariamente das 08h30 às 17h30', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', true, false),

-- SOCORRO
    ('33000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000001', 'Próxima Aventura Rafting & Ecoturismo', 'proxima-aventura-rafting-socorro', 'Operadora pioneira de rafting no Rio do Peixe com botes modernos, instrução de segurança internacional, duck e tirolesas.', 'Estrada Socorro / Munhoz, km 4,5 - Corredor do Rio do Peixe, Socorro - SP', '(19) 3895-1234', '5519998771234', 'proximaaventura_socorro', 'https://proximaaventura.com.br', 90, 220, 'Segunda a Domingo: 08h30 às 18h00', '/images/socorro/aventura.webp', 'published', 'premium', true, true),
    ('33000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000002', 'Mirante Pedra Bela Vista Bar & Gastronomia', 'mirante-pedra-bela-vista-socorro', 'O mirante mais famoso de Socorro a 1.250m de altitude com pôr do sol inesquecível, Pan de Palo na fogueira, chope artesanal e rock acústico.', 'Estrada Municipal dos Goularts, s/n - Bairro Bela Vista, Socorro - SP', '(19) 3895-2000', '5519998882000', 'pedrabelavista', 'https://pedrabelavista.com.br', 40, 130, 'Quarta a Domingo: 12h00 às 21h00', '/images/socorro/hero.webp', 'published', 'premium', true, true),
    ('33000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000002', 'Gruta do Anjo Parque Ecológico', 'gruta-do-anjo-parque-ecologico', 'Antiga mina desativada com lago interior de água mineral cristalina e passeios em pedalinhos entre galerias de rocha esculpidas.', 'Estrada Socorro / Munhoz, km 1 - Bairro dos Leais, Socorro - SP', '(19) 3895-3000', '5519997773000', 'grutadoanjosocorro', 'https://grutadoanjo.com.br', 35, 70, 'Terça a Domingo: 09h00 às 17h00', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', true, false),
    ('33000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000007', 'Hotel Fazenda Campo dos Sonhos', 'hotel-fazenda-campo-dos-sonhos', 'Resort rural premiado internacionalmente pelo turismo sustentável e 100% acessível. Cavalgadas, tirolesas acessíveis, piscinas aquecidas e pensão completa.', 'Estrada dos Sonhos, km 6 - Bairro Lavras de Baixo, Socorro - SP', '(19) 3895-4000', '5519996664000', 'campodossonhos', 'https://campodossonhos.com.br', 680, 1950, 'Recepção 24 horas', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('33000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000001', 'Parque de Aventura Monjolinho', 'parque-de-aventura-monjolinho', 'Complexo de lazer às margens do Rio do Peixe com tirolesas que cruzam corredeiras, arvorismo, cachoeiras e restaurante caipira.', 'Estrada Socorro / Munhoz, km 6 - Corredor Turístico do Rio do Peixe, Socorro - SP', '(19) 3895-5000', '5519995555000', 'parquemonjolinho', 'https://parquemonjolinho.com.br', 25, 180, 'Todos os dias das 09h00 às 17h30', 'https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1000&q=80', 'published', 'premium', true, true),
    ('33000000-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000005', 'Cervejaria Quinta do Malte', 'cervejaria-quinta-do-malte', 'Cervejaria artesanal com fábrica própria e taproom em Socorro. Chopes produzidos com água pura mineral da Mantiqueira e petiscos alemães.', 'Rodovia Pompeu Conti, 3230 - Bairro Salto, Socorro - SP', '(19) 3895-6000', '5519994446000', 'quintadomalte', 'https://quintadomalte.com.br', 35, 120, 'Quarta a Domingo das 11h00 às 22h00', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', true, false),
    ('33000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000004', 'Restaurante Saloon Caipira', 'restaurante-saloon-caipira', 'Comida da roça no fogão a lenha às margens do Rio do Peixe: costela no bafo, leitoa à pururuca, feijão tropeiro e doces caseiros.', 'Estrada Socorro / Munhoz, km 5,5 - Rio do Peixe, Socorro - SP', '(19) 3895-7000', '5519993337000', 'salooncaipirasocorro', NULL, 65, 140, 'Sexta a Domingo e Feriados: 11h30 às 16h30', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1000&q=80', 'published', 'highlight', false, false),
    ('33000000-0000-0000-0000-000000000008', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000006', 'Circuito das Malhas Outlet Socorro', 'circuito-das-malhas-outlet-socorro', 'Mais de 50 lojas de fábrica com moda tricô, malharia e couro a preços de atacado e varejo, com praça de alimentação e amplo estacionamento.', 'Rodovia Deputado Antonio Silva Cunha Bueno, km 4 - Bairro Nogueiras, Socorro - SP', '(19) 3895-8000', '5519992228000', 'circuitodasmalhas.socorro', NULL, 30, 350, 'Aberto diariamente das 09h00 às 18h30', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1000&q=80', 'published', 'free', false, false),
    ('33000000-0000-0000-0000-000000000009', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000003', 'Pousada Vale das Orquídeas', 'pousada-vale-das-orquideas-socorro', 'Refúgio de charme em um vale verdejante com chalés privativos com hidromassagem dupla e lareira, piscina com borda infinita e café colonial.', 'Estrada Municipal da Pompeia, 1500 - Bairro da Pompeia, Socorro - SP', '(19) 3895-9000', '5519991119000', 'valedasorquideassocorro', NULL, 420, 980, 'Check-in: 14h / Check-out: 12h', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1000&q=80', 'published', 'free', false, false),
    ('33000000-0000-0000-0000-000000000010', '00000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000002', 'Mirante do Cristo Redentor de Socorro', 'mirante-do-cristo-redentor-socorro', 'Mirante urbano com vista panorâmica de toda a cidade de Socorro, o curso do Rio do Peixe e a Serra da Mantiqueira.', 'Estrada do Cristo, s/n - Morro do Cristo, Socorro - SP', '(19) 3895-1000', '5519998771000', NULL, NULL, 0, 0, 'Acesso livre diariamente', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1000&q=80', 'published', 'free', false, false)
