-- 4. EXPERIÊNCIAS REAIS (EXPERIENCES)
INSERT INTO public.experiences (id, city_id, business_id, category_id, name, slug, description, price, duration, main_image_url, status, is_featured)
VALUES
    ('12000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', '11000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'Tour das Caves & Degustação Orientada de Vinhos Finos', 'tour-das-caves-degustacao-orientada-vinicola-goes', 'Visita guiada aos parreirais e caves subterrâneas de carvalho, com degustação de 5 vinhos finos premiados e tábua de queijos artesanais.', 95, '1h45', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=800&q=80', 'published', true),
    ('12000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000001', '11000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000001', 'Piquenique Colonial nos Vinhedos Açorianos', 'piquenique-colonial-vinhedos-quinta-do-olivardo', 'Toalha estendida na grama dos vinhedos com cesta colonial recheada de pães, pastéis de nata quentinhos, bolinhos de bacalhau e espumante da casa.', 180, '2h30', 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?auto=format&fit=crop&w=800&q=80', 'published', true),
    ('12000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000001', '11000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000004', 'Passaporte Aventura & Pistas de Neve no Ski Park', 'passaporte-aventura-ski-mountain-park', 'Pistas de esqui e snowboard com equipamentos, tobogã panorâmico gigante de 350m, circuito de tirolesa e arvorismo.', 130, '4 horas', 'https://images.unsplash.com/photo-1551698618-1dfe5d97d256?auto=format&fit=crop&w=800&q=80', 'published', true),

    ('23000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', '22000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000002', 'Voo Duplo de Parapente com Instrutor na Pedra Grande', 'voo-duplo-parapente-pedra-grande-atibaia', 'Decole a 1.418m de altitude e sobrevoe montanhas e lagos com piloto homologado CBVL, fotos e vídeos em 4K.', 450, '2h00', 'https://images.unsplash.com/photo-1507034589631-9433cc6bc453?auto=format&fit=crop&w=800&q=80', 'published', true),
    ('23000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', '22000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000006', 'Colheita de Morangos nas Estufas & Degustação Colonial', 'colheita-de-morangos-takebayashi', 'Colha morangos frescos nas estufas suspensas, visite o orquidário de espécies raras e deguste taça de morango com chantilly artesanal.', 65, '1h30', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=800&q=80', 'published', true),
    ('23000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000002', '22000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000003', 'Tour Cervejeiro & Degustação Harmonizada no Freising Haus', 'tour-cervejeiro-freising-haus', 'Tour técnico pelos tanques da cervejaria bávara com mestre-cervejeiro e degustação de 4 chopes harmonizados com petiscos alemães.', 85, '1h45', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=800&q=80', 'published', true),

    ('34000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000003', '33000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001', 'Descida Radical de Rafting no Rio do Peixe', 'descida-radical-rafting-rio-do-peixe-socorro', '4 a 7 km de corredeiras no Rio do Peixe com guias especializados da IRF, salto da pedra, surf no bote e fotos em alta resolução.', 110, '2h30', '/images/socorro/aventura.webp', 'published', true),
    ('34000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000003', '33000000-0000-0000-0000-000000000002', '30000000-0000-0000-0000-000000000002', 'Experiência Pôr do Sol & Pan de Palo na Pedra Bela Vista', 'experiencia-por-do-sol-pan-de-palo-pedra-bela-vista', 'Entardecer no cume da Pedra Bela Vista a 1.250m de altitude com Pan de Palo assado na fogueira, chope artesanal e música ao vivo.', 60, '3 horas', '/images/socorro/hero.webp', 'published', true),
    ('34000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000003', '33000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000002', 'Passeio de Pedalinho no Lago Cristalino da Gruta do Anjo', 'passeio-pedalinho-gruta-do-anjo', 'Navegue pelas águas esmeraldas de uma caverna inundada com paredes de quartzo e formações minerais.', 45, '1 hora', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', 'published', true)
