    ('13000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'Roteiro Clássico do Vinho e Gastronomia Portuguesa', 'roteiro-classico-do-vinho-sao-roque', 'O itinerário perfeito de 1 dia na Estrada do Vinho. Parreirais, caves históricas, almoço português autêntico e pastéis de nata ao entardecer.', '1 Dia Completo', 'Casal & Família', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=800&q=80', 'published'),
    ('24000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', 'Roteiro Clássico: Pedra Grande, Parque Zanoni e Sabores da Alameda', 'roteiro-classico-pedra-grande-atibaia', 'O roteiro indispensável para quem visita Atibaia em 1 dia. Mirante na Pedra Grande, Parque Zanoni e alta gastronomia na Alameda Lucas.', '1 Dia Completo', 'Aventura & Gastronomia', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80', 'published'),
