    ('14000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', '11000000-0000-0000-0000-000000000001', 'Pisa da Uva & Vindima de São Roque 2026', 'Colheita da uva nos parreirais e a tradicional pisa nas tinas com música típica italiana e portuguesa.', '2026-09-18', '10h00 às 16h00', 'Vinícola Góes - Estrada do Vinho, km 9, São Roque - SP', 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?auto=format&fit=crop&w=800&q=80', 'published'),
